using System;
using System.Text.Json.Serialization;

using Heresy.Core.Objects;

namespace Heresy.Core.Sequences;

/// <summary>
/// Original, unmodified C# source span of the complete Play(...) invocation, generated by the
/// editor-only Roslyn rewrite. Never stored in an authored song.
/// </summary>
public readonly record struct SequenceCallsite(int Start, int Length);

/// <summary>
/// One pattern invocation in a data-driven sequence. StartRow skips complete
/// pattern rows without executing them; their timing is evaluated from the
/// sequencing state in effect on entry.
/// </summary>
public sealed record SequenceEntry
{
	public SequenceEntry(ObjectId patternId, int startRow = 0)
	{
		if (startRow < 0)
			throw new ArgumentOutOfRangeException(nameof(startRow));

		PatternId = patternId;
		StartRow = startRow;
	}

	public ObjectId PatternId { get; }

	public int StartRow { get; }

	/// <summary>Optional editor-audition provenance, null for all ordinary
	/// Sequence entries. Copying source metadata does not alter musical data.</summary>
	[JsonIgnore]
	public SequenceCallsite? EditorCallsite { get; init; }

	public void Deconstruct(out ObjectId patternId, out int startRow)
	{
		patternId = PatternId;
		startRow = StartRow;
	}
}
